// Loader of the guides of the administration (delegated admin, super admin), generated by
// scripts/build-help.mjs. Kept apart from publicGuides.ts so that the public bundle does not even
// reference these guides.
import { createHelpLoader } from './load';
import type { HelpGuideSet } from './types';

const loader = createHelpLoader(import.meta.glob<{ default: HelpGuideSet }>('./generated/*-admin.ts'));

/** Loads the admin guides in a language (English when the language has none). */
export function loadAdminGuides(lang: string): Promise<HelpGuideSet> {
  return loader('admin', lang);
}
